from engine import span
def build(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    P = []
    P.append(dict(role='purpose', text='Con Garcilaso de la Vega la poesía castellana adopta las formas italianas del Renacimiento: el verso endecasílabo, el soneto, la lira, la égloga. Este capítulo recorre su biografía de soldado y poeta, sus obras, la revolución métrica que introdujo y el modo en que se publicó y se leyó su obra durante el siglo XVI.',
        quotes=[Q('es_garcilaso','Es reconocido como uno de los poetas españoles más destacados del Renacimiento'), Q('en_garcilaso','he was the most influential poet to introduce Italian Renaissance verse forms, poetic techniques, and themes to Spain')]))
    P.append(dict(text='Garcilaso nació en Toledo en fecha incierta: las fuentes sitúan el nacimiento entre 1491 y 1503, y la incertidumbre es un recordatorio de que las biografías renacentistas tienen huecos. Recibió una educación cortesana esmerada, aprendió latín, griego, italiano y francés, y conoció en 1519 a Juan Boscán, su gran amigo. En 1520 entró al servicio de Carlos I y en 1523 fue armado caballero de la Orden de Santiago. Murió el 14 de octubre de 1536 en Niza, a consecuencia de una herida recibida en combate.',
        quotes=[Q('es_garcilaso','Nacido en Toledo entre 1491 y 1503'), Q('en_garcilaso','Garcilaso de la Vega died on 14 October 1536 in Nice')]))
    P.append(dict(text='Su vida es la de un soldado-poeta, representante del tópico renacentista de las armas y las letras. Luchó en la guerra de las Comunidades, participó en la campaña de Fuenterrabía, acompañó al emperador por Europa y sufrió un breve destierro en una isla del Danubio cerca de Ratisbona, que describe en su Canción III. El propio Garcilaso se definió atrapado en esta dualidad con el verso «tomando ora la espada, ora la pluma».',
        quotes=[Q('es_garcilaso','Se le apresó en Tolosa y se acordó confinarlo en una isla del Danubio cerca de Ratisbona, descrita por el poeta en su Canción III.'), Q('en_garcilaso','representative of the contemporaneous motif of las armas y las letras')]))
    P.append(dict(text='La poesía de Garcilaso se divide en etapas. Antes de su estancia en Nápoles (1522-1523 y 1533) su verso no estaba marcado por rasgos petrarquistas; en Nápoles descubrió a los autores italianos, entre ellos Petrarca y Sannazaro, cuya Arcadia le inspiró el mundo pastoril, y fortaleció su clasicismo con la lectura de Virgilio, Ovidio y Horacio. La crítica distingue así un período español, de versos octosílabos; otro petrarquista, de sonetos y canciones, y otro clasicista, de églogas, elegías y epístolas.',
        quotes=[Q('es_garcilaso','Antes de ir a Nápoles su poesía no estaba marcada por rasgos petrarquistas','autores italianos'), Q('en_garcilaso','During his Spanish period, he wrote the majority of his eight-syllable poems','his other more classical poems')]))
    P.append(dict(text='La novedad decisiva es métrica. Garcilaso adaptó al castellano el verso endecasílabo, de once sílabas, más flexible que el rígido y monótono dodecasílabo, y con él introdujo, junto con Boscán y Diego Hurtado de Mendoza, el terceto, el soneto, la lira, la octava real, los endecasílabos sueltos y la canción en estancias. La lira se compone de tres versos de siete sílabas y dos de once; la estancia combina endecasílabos y heptasílabos. Una de las fuentes resume el efecto así: la poesía española no volvió a ser la misma.',
        quotes=[Q('es_garcilaso','introducir con Juan Boscán y Diego Hurtado de Mendoza una serie de estrofas','petrarquismo'), Q('en_garcilaso','the "lira", formed by three seven-syllable and two eleven-syllable lines'), Q('en_garcilaso','It can be said that Spanish poetry was never the same after Garcilaso de la Vega.')]))
    P.append(dict(text='Su obra es breve: cuarenta sonetos, cinco canciones, ocho coplas castellanas, tres églogas, dos elegías y una epístola, además de una oda en liras y de composiciones latinas. Se publicó póstumamente en 1543, como apéndice de las obras de Juan Boscán, por iniciativa de su viuda, y se reimprimió casi cada año durante más de una década. En 1569 un librero salmantino publicó por primera vez solo la poesía de Garcilaso, edición que sirvió de base a la comentada del Brocense (1574), a la que siguió la de Fernando de Herrera en 1580.',
        quotes=[Q('es_garcilaso','compuesta por cuarenta sonetos, cinco canciones, una oda en liras, dos elegías, una epístola, tres églogas y ocho coplas castellanas'), Q('es_garcilaso','En 1580 se publicó en Sevilla otra edición comentada'), Q('en_garcilaso','His works include: forty Sonetos (Sonnets), five Canciones (Songs), eight Coplas (Couplets), three Églogas (Eclogues), two Elegías (Elegies), and the Epístola a Boscán (Letter to Boscán).')]))
    P.append(dict(text='El estilo de Garcilaso se caracteriza por la claridad y la naturalidad, en línea con el ideal lingüístico de su amigo Juan de Valdés: selección de palabras, precisión y preferencia por las voces usuales sobre los cultismos. Cuida además la musicalidad mediante la aliteración y un ritmo apoyado en los ejes del endecasílabo. En su Égloga tercera defiende evitar la retórica pomposa para que la poesía parezca sincera y espontánea: el objetivo de la poesía es comunicar sentimientos, no despertar admiración cortesana.',
        quotes=[Q('es_garcilaso','El lenguaje de Garcilaso es claro y nítido'), Q('en_garcilaso','Allusions to classical myths and Greco-Latin figures, great musicality, alliteration, rhythm and an absence of religion characterize his poetry.')]))
    P.append(dict(text='La influencia posterior fue inmensa. La crítica lo considera el «príncipe de los poetas castellanos» y el paradigma del poeta-soldado; su obra influyó en la mayoría de los poetas posteriores, como Fray Luis de León, San Juan de la Cruz, Cervantes, Lope de Vega, Góngora y Quevedo. Poetas del siglo XX como Rafael Alberti y Miguel Hernández le dedicaron homenajes poéticos, y el término garcilasismo designa una corriente de posguerra.',
        quotes=[Q('es_garcilaso','contribuyendo a su exaltación como “príncipe de los poetas castellanos”'), Q('en_garcilaso','His works have influenced the majority of subsequent Spanish poets')]))
    P.append(dict(role='definition', text='Endecasílabo: verso de once sílabas métricas que Garcilaso adaptó del modelo italiano y que se convirtió en el verso principal de la poesía culta castellana. Permite componer sonetos, tercetos, liras y octavas reales.',
        quotes=[Q('es_garcilaso','el verso endecasílabo y su ritmo tritónico, mucho más flexible que el rígido y monótono del dodecasílabo'), Q('en_garcilaso','Garcilaso adapted the eleven-syllable line to the Spanish language in his sonetos')]))
    P.append(dict(role='consejo', text='Al leer un soneto de Garcilaso, marque los acentos de cada endecasílabo y observe cómo las sinalefas reducen las sílabas gramaticales a once métricas. Comprobará que la flexibilidad del verso nace de la combinación de acentos, no de una medida mecánica.',
        quotes=[Q('es_garcilaso','El estilo de Garcilaso es muy característico: cuida especialmente la musicalidad del verso'), Q('en_garcilaso','Increasing the number of syllables in the verse from eight to eleven allowed for greater flexibility.')]))
    P.append(dict(role='self_check', text='¿Qué estrofas introdujo Garcilaso en la poesía castellana? ¿Por qué se dice que su etapa napolitana marcó un cambio en su obra? ¿Cómo se publicó su poesía en el siglo XVI y qué papel desempeñó el Brocense?',
        quotes=[Q('es_garcilaso','En marzo de 1542, Boscán y su mujer firmaron un contrato'), Q('en_garcilaso','His poetry was published posthumously by Juan Boscán in 1543')]))
    return P

def problems(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    return [dict(role='worked', problem_type='NUMERICAL',
        prompt='Las fuentes coinciden en que Garcilaso escribió cuarenta sonetos, cinco canciones, ocho coplas castellanas, tres églogas, dos elegías y una epístola. Calcule cuántas composiciones castellanas suman estas categorías y qué porcentaje de ellas son sonetos (sin contar la oda en liras, que solo cita una de las fuentes).',
        expected='67.8', quotes=[Q('es_garcilaso','compuesta por cuarenta sonetos, cinco canciones, una oda en liras, dos elegías, una epístola, tres églogas y ocho coplas castellanas'), Q('en_garcilaso','His works include: forty Sonetos (Sonnets), five Canciones (Songs), eight Coplas (Couplets), three Églogas (Eclogues), two Elegías (Elegies), and the Epístola a Boscán (Letter to Boscán).')],
        method='Suma de categorías y proporción porcentual',
        solution=dict(given=[dict(symbol='n_s',value=40,unit='dimensionless',meaning='sonetos'),dict(symbol='n_c',value=5,unit='dimensionless',meaning='canciones'),dict(symbol='n_o',value=8,unit='dimensionless',meaning='coplas castellanas'),dict(symbol='n_e',value=3,unit='dimensionless',meaning='églogas'),dict(symbol='n_l',value=2,unit='dimensionless',meaning='elegías'),dict(symbol='n_p',value=1,unit='dimensionless',meaning='epístola')],
          unknown='El total de composiciones contadas y el porcentaje de sonetos.',
          model=[dict(name='Total de composiciones',latex='N = n_s + n_c + n_o + n_e + n_l + n_p',symbolic='n_s+n_c+n_o+n_e+n_l+n_p'),dict(name='Porcentaje de sonetos',latex='p_s = 100\\,\\frac{n_s}{N}',symbolic='100*n_s/N')],
          assumptions=['Se cuentan solo las categorías comunes a las dos fuentes; la oda en liras y las composiciones latinas quedan fuera.'],
          development=['Cada categoría se cuenta una sola vez, y el porcentaje se calcula sobre el total de esas categorías.'],
          steps=[dict(text='Composiciones castellanas contadas',equation='N = 40 + 5 + 8 + 3 + 2 + 1',expression='40+5+8+3+2+1',expected=59,unit='dimensionless'),
                 dict(text='Porcentaje de sonetos',equation='p_s = 100 \\cdot 40/59',expression='100*40/59',expected=67.7966,unit='dimensionless')],
          result='Suman 59 composiciones, y aproximadamente el 67,8 % son sonetos.',
          interpretation='Dos de cada tres composiciones son sonetos, lo que muestra hasta qué punto la forma italiana ocupa el centro de su obra.',
          limitations=['La cifra cambia si se incluye la oda en liras: 60 composiciones y 66,7 % de sonetos.'],
          mistakes=['Incluir en el total las composiciones latinas, que no pertenecen a la obra en castellano.']))]
